
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m06_2x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m06_2x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-9.969801831172606e-02, -9.788781802120555e-02, -9.527005924587820e-02, -9.148094280654344e-02, -8.599949426075465e-02, -7.811558790840570e-02, -6.702224746737323e-02, -5.249238215939241e-02, -3.731383312366147e-02, -2.853402443533807e-02, -2.955094315030616e-02, -7.355562008995535e-02, -3.602106361700760e-02, -2.513568107518598e-02, -1.440137992856131e-02, 6.546422467736884e-03, 2.395955857903881e-02, 6.417741642899355e-03, 4.378022514174093e-04, -5.246166619212935e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


